import{_ as o,o as c,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const a="/architecture-zh-CN.svg",u=JSON.parse('{"title":"架构设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/architecture.md","filePath":"zh-CN/dev-guide/architecture.md","lastUpdated":1783414071000}'),t={name:"zh-CN/dev-guide/architecture.md"};function d(s,e,l,n,h,p){return c(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h1><p><img src="'+a+'" alt="SwiftList 架构图"></p><h2 id="进程拆分" tabindex="-1">进程拆分 <a class="header-anchor" href="#进程拆分" aria-label="Permalink to &quot;进程拆分&quot;">​</a></h2><p>SwiftList 运行为三个独立进程，按权限级别和生命周期有意拆分:</p><ul><li><strong><code>SwiftList.Service</code></strong> —— 一个以 <code>LocalSystem</code> 身份运行的 Windows 服务。它负责全部文件索引工 作:读取本地磁盘的 NTFS USN 日志与 MFT、扫描并缓存网络共享，并通过命名管道回答搜索查询。在 SYSTEM 级别运行意味着它可以读取所有用户账户都被允许看到的原始卷元数据，而不需要让交互式的 App 进程获得它本不需要的提升权限。</li><li><strong><code>SwiftList.App</code></strong> —— 用户态、Session 级别的 WPF 应用:搜索窗口、设置窗口、热键处理、动作菜 单/QuickLook 界面都在这里。它通过命名管道(<code>Core.Services</code> 里的 <code>SearchService</code>/ <code>UsnServicePipeServer</code>)和 Service 通信，从不直接访问磁盘索引。</li><li><strong><code>SwiftList.Service --hook</code></strong> —— 一个独立的小进程，专门托管低层级全局键盘钩子，这样钩子崩溃 或者某个前台应用行为异常都不会连累主 App 进程。</li></ul><h2 id="共享的-core" tabindex="-1">共享的 Core <a class="header-anchor" href="#共享的-core" aria-label="Permalink to &quot;共享的 Core&quot;">​</a></h2><p><code>Core</code> 是一个被 Service 和 App 同时引用的类库。它包含:</p><ul><li>搜索引擎(<code>Core/SearchIndex/Fzf/*</code>)—— 一套仿照 <code>fzf</code> 命令行工具算法实现的模糊匹配引擎，配合 一个查询解析器(<code>SearchQueryParser</code>)处理盘符定向和路径模式搜索。</li><li>运行时索引(<code>Core/SearchIndex/RecordIndex/*</code>、<code>RecordSearch/*</code>)—— 由 USN/MFT 读取结果构建的 内存结构，随变更增量更新。</li><li>IPC 契约(<code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等)—— App 和 Service 两边 完全共用同一份定义，保证双方对线路格式的理解始终一致。</li><li><code>Logger</code> —— 写入各进程独立的日志文件(<code>service.log</code>、<code>app.log</code>、<code>hook.log</code>)，都可以在 App 的 设置 → 运行状态 日志查看器里读取(但不是都能直接写入)。</li></ul><h2 id="插件在架构中的位置" tabindex="-1">插件在架构中的位置 <a class="header-anchor" href="#插件在架构中的位置" aria-label="Permalink to &quot;插件在架构中的位置&quot;">​</a></h2><p>插件是引用 <code>PluginSdk</code> 的 <code>.dll</code> 程序集，由 App 进程加载(见<a href="./getting-started.html">快速上手</a>和 <a href="./packaging.html">打包与发布</a>)。SwiftList 自带两个插件作为一等公民示例—— <code>SwiftList.Plugins.CoreExtensions</code>(内置文件动作与 Shell 右键菜单集成)和 <code>SwiftList.Plugins.PinyinAlias</code>(中文文件名拼音别名)——参见<a href="./examples.html">插件示例</a>了解这两个插 件的详细走读。</p><p>插件从不直接和 Service 通信;它们通过插件 SDK 参考里记录的接口和 App 交互，如果需要索引自定义目 录，则通过 <code>DirectoryIndexerService</code> 代为向 Service 转发请求。</p>',11)])])}const f=o(t,[["render",d]]);export{u as __pageData,f as default};
